// frontend/src/components/ChatInput.js
import React, { useState } from "react";

export default function ChatInput({ onSend, onUpload, loading, areasHint, fileHint }) {
  const [text, setText] = useState("");
  const [file, setFile] = useState(null);

  const submit = (e) => {
    e.preventDefault();
    if (!text.trim()) return;
    onSend(text.trim());
    setText("");
  };

  const onFileChange = (ev) => {
    const f = ev.target.files[0];
    setFile(f);
  };

  const upload = async () => {
    if (!file) return alert("Choose an Excel file (.xlsx)");
    await onUpload(file);
    setFile(null);
    document.getElementById("file-input").value = "";
  };

  return (
    <div>
      <form onSubmit={submit} className="d-flex">
        <input
          className="form-control me-2"
          placeholder="Ask: Analyze Wakad"
          value={text}
          onChange={(e) => setText(e.target.value)}
          disabled={loading}
        />
        <button className="btn btn-primary" type="submit" disabled={loading}>Send</button>
      </form>

      <div className="mt-2 d-flex align-items-center">
        <input id="file-input" type="file" accept=".xlsx" onChange={onFileChange} className="form-control form-control-sm me-2" />
        <button className="btn btn-secondary btn-sm" onClick={upload} disabled={loading || !file}>Upload Excel</button>
      </div>

      <div className="mt-2">
        {fileHint && <div className="text-warning small">{fileHint}</div>}
        {areasHint && areasHint.length > 0 && <div className="small">Known areas: {areasHint.slice(0,8).join(", ")}{areasHint.length > 8 ? ", ..." : ""}</div>}
      </div>
    </div>
  );
}
